"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[536],{6286:(e,a,t)=>{t.d(a,{L:()=>n});let n=Object.entries({"hang-khay":["Row of the lacquered trays","Khay are the lacquered trays and betel boxes once sold along this short lake street."],"hang-bai":["Row of the playing cards","Bai are playing cards; the street traded in cards and paper goods."],"hang-trong":["Row of the drums","Trong are drums, and the street is also home to the Hang Trong folk painting tradition."],"hang-hanh":["Row of the luggage sellers","Hanh is short for hanh ly, luggage; the bag shops near the lake keep the trade."],"cau-go":["The wooden bridge","Named for a wooden bridge that once crossed the stream feeding Hoan Kiem Lake."],"hang-gai":["Row of the silk and hemp","Gai covers the silk and hemp goods that made this the quarter's most elegant street."],"hang-bong":["Row of the cotton","Bong is cotton; the street sold cotton, quilts and bedding."],"hang-da":["Row of the leather","Da is leather, and shoe, bag and belt workshops still line the street."],"hang-hom":["Row of the wooden chests","Hom are wooden chests; suitcase and school bag shops replaced the chest makers."],"hang-dao":["Row of the silk dyers","Dao is tied to the silk trade that made this street the spine of the quarter."],"hang-ngang":["The crosswise row","Ngang means across: a cross street of premium cloth traders running off the spine."],"hang-duong":["Row of the sugar","Duong is sugar: preserved fruit, candied sweets and Tet gift boxes."],"hang-bo":["Row of the bamboo baskets","Bo are the bamboo baskets and woven ware sold near the market crossroads."],"dong-xuan":["Dong Xuan, the great market","The name of Hanoi's largest covered market, trading since the French era."],"hang-dau":["Row of the beans","Dau are beans; dry goods and bean traders worked under the Long Bien bridge approach."],"hang-giay":["Row of the paper","Giay is paper, from votive paper to packaging for the market area."],"hang-khoai":["Row of the sweet potatoes","Khoai are sweet potatoes; a market edge street of produce stalls."],"hang-chieu":["Row of the mats","Chieu are woven mats, sold a short walk from the old East Gate."],"cau-dong":["The market bridge street","A trading street feeding Dong Xuan Market from the east."],"hang-bac":["Row of the silver","Bac is silver: the street where Hanoi's silver and jewellery trade began."],"hang-ma":["Row of the votive paper","Ma here is the paper offerings burned for ancestors, plus festival lanterns and decor."],"hang-luoc":["Row of the combs","Luoc are combs, once part of every wedding trousseau in the city."],"hang-ruoi":["Row of the sand worms","Ruoi are the seasonal sand worms behind cha ruoi, the autumn omelette."],"hang-chai":["Row of the bottles","Chai are bottles; the bottle traders gave way to small local eateries."],"ta-hien":["Ta Hien street","A street name kept from the old quarter's street plan, now famous as the bia hoi corner."],"ma-may":["Ma May street","A heritage street of preserved shophouses; the name predates its food fame."],"hang-buom":["Row of the sails","Buom are woven sails and mats; a guild street of the Chinese community turned food street."],"hang-mam":["Row of the fish sauce","Mam is fish sauce and fermented pastes, supplying kitchens across the quarter."],"hang-muoi":["Row of the salt","Muoi is salt, once a traded staple; today the street mixes snacks and coffee."],"hang-be":["Row of the rafts","Be are the timber rafts of the Red River trade that once landed nearby."],"dao-duy-tu":["Dao Duy Tu street","Named for Dao Duy Tu, the scholar and mandarin; an evening street of tea houses and snacks."],"lan-ong":["Lan Ong street","Named after Hai Thuong Lan Ong, the master physician of traditional medicine."],"thuoc-bac":["Northern medicine street","Thuoc Bac means northern, or Chinese, medicine: wholesale herbs stacked to the ceiling."],"hang-vai":["Row of the fabric","Vai is fabric, traded to tailors and garment makers across the city."],"hang-thiec":["Row of the tin","Thiec is tin; tinsmiths still hammer pots and trays from sheet metal."],"hang-dong":["Row of the copper","Dong here is copper and bronze: incense burners, pots and cast ware."],"hang-dieu":["Row of the pipes","Dieu are tobacco pipes and their accessories."],"hang-cot":["Row of the bamboo screens","Cot are woven bamboo screens and shades."],"hang-ga":["Row of the chickens","Ga are chickens; the old poultry street is now a local shopping street."],"hang-tre":["Row of the bamboo","Tre is bamboo, worked into baskets, ladders and craft goods."],"hang-thung":["Row of the buckets","Thung are lacquered bamboo buckets, once made along this street."],"hang-bat":["Row of the bowls","Bat are bowls and dishes for every kitchen in the quarter."],"hang-non":["Row of the hats","Non are hats, above all the conical palm hat."],"hang-may":["Row of the rattan","May is rattan, woven into baskets, lamps and furniture."],"hang-than":["Row of the charcoal","Than is charcoal; the street later became known for banh com green rice cakes."],"phung-hung":["Phung Hung street","The mural street under the railway arches, painted with scenes of old Hanoi."],"le-duan-train-street":["Le Duan train street","The southern train street section along Le Duan, visited only under current access rules."],"tran-phu-train-street":["Tran Phu train street","The cafe lined train street section along Tran Phu, visited only under current access rules."],"cha-ca":["Cha Ca street","Named after cha ca, the turmeric fish with dill that made the street famous."]}).map(e=>{let[a,[t,n]]=e;return{slug:a,literal:t,note:n,audio:null}})},7455:(e,a,t)=>{t.d(a,{JL:()=>r,oy:()=>s});let n=(e,a,t,n)=>({name:e,slug:a,trade:t,line:n,geo:o[a]}),o={"cau-dong":[21.03785,105.84987],"cau-go":[21.03206,105.85215],"cha-ca":[21.03571,105.84919],"dao-duy-tu":[21.03545,105.85295],"dong-xuan":[21.03907,105.84973],"hang-bac":[21.03289,105.85284],"hang-bai":[21.02541,105.85322],"hang-bat":[21.03379,105.84746],"hang-be":[21.0333,105.85391],"hang-bo":[21.03489,105.84793],"hang-bong":[21.0269,105.84614],"hang-buom":[21.03607,105.85218],"hang-chai":[21.03748,105.84754],"hang-chieu":[21.0371,105.85078],"hang-cot":[21.03978,105.84717],"hang-da":[21.03136,105.84612],"hang-dao":[21.0335,105.85127],"hang-dau":[21.04053,105.84909],"hang-dieu":[21.03284,105.84693],"hang-dong":[21.03607,105.84768],"hang-duong":[21.03683,105.84836],"hang-ga":[21.0343,105.84711],"hang-gai":[21.03203,105.8492],"hang-giay":[21.03913,105.84816],"hang-hanh":[21.03164,105.85076],"hang-hom":[21.03186,105.84881],"hang-khay":[21.02572,105.85243],"hang-khoai":[21.03792,105.84834],"hang-luoc":[21.03815,105.84764],"hang-ma":[21.03729,105.84663],"hang-mam":[21.03386,105.85505],"hang-muoi":[21.03472,105.85476],"hang-ngang":[21.03413,105.85065],"hang-non":[21.03268,105.84658],"hang-ruoi":[21.03712,105.84791],"hang-thiec":[21.03313,105.84782],"hang-thung":[21.03225,105.85404],"hang-tre":[21.03195,105.85565],"hang-trong":[21.02747,105.84954],"hang-vai":[21.03558,105.84675],"lan-ong":[21.0354,105.84906],"le-duan-train-street":[21.02324,105.8412],"ma-may":[21.03594,105.85323],"phung-hung":[21.03403,105.84572],"ta-hien":[21.0353,105.85199],"thuoc-bac":[21.03577,105.84832],"tran-phu-train-street":[21.03124,105.84485]},s=[{id:"C1",slug:"lake-and-south-gate",name:"The Lake and the South Gate",short:"Lake & South Gate",color:"#0E7C7B",v:"var(--area-c1)",theme:"Hoan Kiem Lake, the Cathedral and sunset walks",story:"Every first trip to Hanoi starts here. Hoan Kiem Lake is the compass of the Old Quarter, and the streets around its southern edge hold the postcard views: the Turtle Tower at golden hour, the red bridge to Ngoc Son Temple, the water puppet theatre and the French era facades of Trang Tien. Come at dawn to share the lake shore with tai chi groups, or at sunset when the whole city seems to slow down for one lap around the water.",streets:[n("H\xe0ng Khay","hang-khay","Lacquered trays and boxes","One of the short streets along the lake, once known for lacquerware trays and betel boxes."),n("H\xe0ng B\xe0i","hang-bai","Playing cards and paper goods","A calm street running south from the lake, historically tied to card and paper trades."),n("H\xe0ng Trống","hang-trong","Folk paintings and drums","Home of the Hang Trong folk painting tradition, printed by hand on paper for Tet and festivals."),n("H\xe0ng H\xe0nh","hang-hanh","Luggage and travel goods","A small street of bag and luggage shops close to the lake and the Cathedral."),n("Cầu Gỗ","cau-go","The old wooden bridge crossing","Named after a wooden bridge that once crossed the stream feeding the lake.")]},{id:"C2",slug:"silk-and-style",name:"Silk and Style",short:"Silk & Style",color:"#118AB2",v:"var(--area-c2)",theme:"Silk, tailoring, galleries and quiet cafes",story:"The south west of the Old Quarter is where Hanoi dresses up. Hang Gai has sold silk for centuries and still lines up tailors, galleries and lacquer shops in elegant shophouses. The side streets slow the pace down: cotton quilts, leather goods and wooden chests from the old trades, mixed today with small hotels and calm cafes. If you buy one thing in the Old Quarter, buy it here, and watch it being made or measured in front of you.",streets:[n("H\xe0ng Gai","hang-gai","Silk and hemp goods","The famous silk street: tailors, embroidery, galleries and lacquerware in heritage shophouses."),n("H\xe0ng B\xf4ng","hang-bong","Cotton quilts and bedding","Once the cotton street, today a long lively mix of bedding shops, street food and hotels."),n("H\xe0ng Da","hang-da","Leather goods","The leather street, still full of shoe, bag and belt workshops and shops."),n("H\xe0ng H\xf2m","hang-hom","Wooden chests, now luggage","Wooden chest makers gave way to suitcase and school bag shops along this street.")]},{id:"C3",slug:"night-market-spine",name:"The Night Market Spine",short:"Night Market Spine",color:"#EF476F",v:"var(--area-c3)",theme:"The weekend night market and sweet preserved fruit",story:"Hang Dao is the spine of the Old Quarter, the street every route crosses. On Friday, Saturday and Sunday nights it closes to traffic and becomes the walking spine of the night market, three kilometres of stalls running north to Dong Xuan. By day this cluster is about silk history, fine fabrics and the sweet shops of Hang Duong, where families buy preserved fruit and traditional sweets for Tet.",streets:[n("H\xe0ng Đ\xe0o","hang-dao","Silk street","The central axis of the Old Quarter and the heart of the weekend night market."),n("H\xe0ng Ngang","hang-ngang","Fine fabrics, now fashion","Once a street of premium cloth traders, today dense with fashion and cosmetics shops."),n("H\xe0ng Đường","hang-duong","Sweets and preserved fruit","The address for o mai preserved fruit, candied sweets and Tet gift boxes."),n("H\xe0ng Bồ","hang-bo","Bamboo baskets and woven ware","Sellers of bamboo baskets, trays and woven household goods near the market crossroads.")]},{id:"C4",slug:"dong-xuan-and-north-gate",name:"Dong Xuan and the North Gate",short:"Dong Xuan & North Gate",color:"#F4A259",v:"var(--area-c4)",theme:"The great market, wholesale streets and the old city gate",story:"The north of the Old Quarter still works for a living. Dong Xuan Market, the largest covered market in Hanoi, feeds the whole quarter with wholesale cloth, dry goods and food. Around it, mat sellers, bean traders and paper shops keep the old guild pattern alive, and a short walk east stands O Quan Chuong, the last surviving gate of the old citadel. Visit in the morning, when the market is at full speed.",streets:[n("Đồng Xu\xe2n","dong-xuan","The great covered market","Hanoi's largest indoor market, three floors of wholesale and retail since the French era."),n("H\xe0ng Đậu","hang-dau","Bean trading","A northern street of bean and dry goods traders beneath the Long Bien bridge approach."),n("H\xe0ng Giấy","hang-giay","Paper goods","Paper sellers serving the market area, from votive paper to packaging."),n("H\xe0ng Khoai","hang-khoai","Sweet potatoes and market produce","A market edge street of produce stalls and small eateries by Dong Xuan."),n("H\xe0ng Chiếu","hang-chieu","Woven mats","The mat sellers' street, a short walk from the old East Gate of the citadel."),n("Cầu Đ\xf4ng","cau-dong","Market bridge street","A busy trading street feeding into Dong Xuan Market from the east.")]},{id:"C5",slug:"silver-paper-festival-crafts",name:"Silver, Paper and Festival Crafts",short:"Silver & Festival Crafts",color:"#B5651D",v:"var(--area-c5)",theme:"Silversmiths, festival paper and Mid Autumn colour",story:"Some streets change with the festival calendar, and this cluster leads them. Hang Ma fills with paper offerings, lanterns and decorations that turn red and gold before Tet and the Mid Autumn Festival. A few steps away, Hang Bac is where Hanoi's silver trade began, with jewellers still working behind small counters, and Hang Luoc sells the combs that once completed every wedding trousseau.",streets:[n("H\xe0ng Bạc","hang-bac","Silver and jewellery","The original silversmiths' street, still lined with jewellers and gold and silver shops."),n("H\xe0ng M\xe3","hang-ma","Votive paper and festival decor","The most colourful street in the quarter before Tet and Mid Autumn, full of lanterns and paper goods."),n("H\xe0ng Lược","hang-luoc","Combs","The comb sellers' street, once supplying wooden and horn combs to the whole city."),n("H\xe0ng Rươi","hang-ruoi","Seasonal sand worm delicacy","A short street famous in season for cha ruoi, the autumn sand worm omelette."),n("H\xe0ng Chai","hang-chai","Bottle trading, now local eateries","A narrow street near the market, today loved for small local food stalls.")]},{id:"C6",slug:"eat-and-drink-east",name:"Eat and Drink in the East",short:"Eat & Drink East",color:"#E8553E",v:"var(--area-c6)",theme:"Bia hoi corner, food streets and late night bowls",story:"When the Old Quarter gets hungry, it walks east. Ta Hien is the famous bia hoi corner where the city sits on small stools with glasses of fresh beer, and the streets around it layer grill smoke, noodle steam and dessert carts into one long evening. Ma May and Hang Buom keep the older food traditions too, from festival sweets to family restaurants that have served the same dishes for decades.",streets:[n("Tạ Hiện","ta-hien","Bia hoi corner","The backpacker corner of Hanoi: fresh beer, grilled food and stools on the pavement."),n("M\xe3 M\xe2y","ma-may","Old food street","A heritage street of preserved shophouses, restaurants and small hotels."),n("H\xe0ng Buồm","hang-buom","Woven sails and mats, now food","A former guild street of the Chinese community, today a busy food street."),n("H\xe0ng Mắm","hang-mam","Fish sauce and dried seafood","The fish sauce street, pungent and proud, supplying kitchens across the quarter."),n("H\xe0ng Muối","hang-muoi","Salt trading, now snacks and coffee","The old salt street, today a local mix of snack shops and coffee corners."),n("H\xe0ng B\xe8","hang-be","Timber rafts, now food market","Named for the timber rafts of the Red River trade, now a fresh food market street."),n("Đ\xe0o Duy Từ","dao-duy-tu","Tea houses and night snacks","An evening street of desserts, tea and late snacks near the bia hoi corner.")]},{id:"C7",slug:"medicine-fabric-old-trades",name:"Medicine, Fabric and Old Trades",short:"Old Trades Centre West",color:"#5B8C5A",v:"var(--area-c7)",theme:"Traditional medicine and the surviving guild crafts",story:"This is the Old Quarter that tourists often miss, and locals still use every day. Lan Ong and Thuoc Bac smell of dried herbs and roots from the traditional medicine trade, named after the great physician Hai Thuong Lan Ong. Around them, a working museum of guild streets survives: tin, copper, fabric, hats, bamboo and rattan, each still selling what its name promises. It is the least crowded cluster and the most rewarding for anyone who loves how things are made.",streets:[n("L\xe3n \xd4ng","lan-ong","Traditional medicine","Shops of roots, herbs and remedies named after the master physician Hai Thuong Lan Ong."),n("Thuốc Bắc","thuoc-bac","Chinese medicine wholesale","The wholesale medicine street, fragrant with dried herbs stacked to the ceiling."),n("H\xe0ng Vải","hang-vai","Fabric","Fabric traders serving tailors and garment makers across the city."),n("H\xe0ng Thiếc","hang-thiec","Tin ware","Tinsmiths hammering pots, trays and kitchen ware from sheet metal."),n("H\xe0ng Đồng","hang-dong","Copper and bronze ware","Copper and bronze sellers, from incense burners to kitchen pots."),n("H\xe0ng Điếu","hang-dieu","Tobacco pipes","The pipe sellers' street, once supplying every kind of tobacco pipe and accessory."),n("H\xe0ng C\xf3t","hang-cot","Woven bamboo screens","Bamboo weavers whose street now mixes craft shops with fashion and food."),n("H\xe0ng G\xe0","hang-ga","Poultry trading","The old poultry street, today a local shopping and food street."),n("H\xe0ng Tre","hang-tre","Bamboo craft","Bamboo and rattan craft sellers keeping a light, patient trade alive."),n("H\xe0ng Th\xf9ng","hang-thung","Lacquered bamboo buckets","Once makers of lacquered bamboo buckets, now mixed local trade."),n("H\xe0ng B\xe1t","hang-bat","Bowls and dishes","The bowl and dish street, today also groceries and household goods."),n("H\xe0ng N\xf3n","hang-non","Hats and conical hats","Hat sellers of every shape, from conical palm hats to modern caps."),n("H\xe0ng M\xe2y","hang-may","Rattan craft","Rattan weavers and sellers of baskets, lamps and furniture."),n("H\xe0ng Than","hang-than","Charcoal, now green rice cakes","The charcoal street that became known for banh com green rice cakes.")]},{id:"C8",slug:"train-street-and-west-edge",name:"Train Street and the West Edge",short:"Train Street & West Edge",color:"#7D5BA6",v:"var(--area-c8)",theme:"Train street, mural street and the way to the basecamp",story:"The western edge is where the Old Quarter exhales. Phung Hung runs under the railway arches, now painted with murals of old Hanoi, and the train streets of Le Duan and Tran Phu draw visitors to watch trains pass a breath from the houses, subject to the current access rules. From here the city opens toward the Temple of Literature, and toward our quiet basecamp streets just outside the quarter.",streets:[n("Ph\xf9ng Hưng","phung-hung","Mural street under the arches","Railway arch murals recreating old Hanoi, a favourite photo walk."),n("L\xea Duẩn","le-duan-train-street","Train street south section","The southern train street section, visit only as current access rules allow."),n("Trần Ph\xfa","tran-phu-train-street","Train street cafe section","The cafe lined train street section, visit only as current access rules allow."),n("Chả C\xe1","cha-ca","Turmeric fish street","The short street named after cha ca, Hanoi's famous turmeric fish with dill.")]}],r=s.flatMap(e=>e.streets.map(a=>({...a,cluster:e})))}}]);